<?php
require_once 'app.php';auth(true);$rows=[];try{$rows=financial($_GET);}catch(Throwable $ex){handleError($ex);}
$received=0;$pending=0;foreach($rows as $r){if($r['pagamento_status']==='Confirmado')$received+=(float)$r['valor'];elseif($r['status']!=='Cancelado' && in_array($r['pagamento_status'],['Pendente','Solicitado'],true))$pending+=(float)$r['valor'];}
pageStart('Financeiro'); ?>
<h1>Histórico financeiro</h1><p class="muted">Filtros pela data do jogo. Pagamentos confirmados permanecem no total recebido mesmo após cancelar a reserva. Pendências canceladas ficam fora do total pendente. Registros antigos “Não se aplica” precisam de confirmação manual do recebimento.</p><form method="get" class="admin-form-card admin-form-grid"><label>Data inicial<input type="date" name="de" value="<?=e($_GET['de']??'')?>"></label><label>Data final<input type="date" name="ate" value="<?=e($_GET['ate']??'')?>"></label><label>Status<select name="status"><option value="">Todos</option><?php foreach(['Pendente','Solicitado','Confirmado','Cancelado'] as $s):?><option <?=($_GET['status']??'')===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></label><label>Forma de pagamento<select name="forma"><option value="">Todas</option><?php foreach(['Pix','Dinheiro','Cartão'] as $s):?><option <?=($_GET['forma']??'')===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></label><button class="primary-btn">Filtrar</button><a href="financeiro.php">Limpar filtros</a></form><section class="stats"><article><div><small>Total recebido</small><strong><?=money($received)?></strong></div></article><article><div><small>Total pendente</small><strong><?=money($pending)?></strong></div></article><article><div><small>Quantidade de pagamentos</small><strong><?=count($rows)?></strong></div></article></section>
<div class="table-card table-scroll"><table><thead><tr><th>Cliente</th><th>Reserva</th><th>Data</th><th>Valor</th><th>Forma</th><th>Status do pagamento</th><th>Status da reserva</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7">Nenhum pagamento encontrado.</td></tr><?php endif;foreach($rows as $r):?><tr><td><?=e($r['nome_cliente'])?></td><td>#<?=(int)$r['id']?></td><td><?=date('d/m/Y',strtotime($r['data']))?></td><td><?=money($r['valor'])?></td><td><?=e($r['forma_pagamento'])?></td><td><?=e($r['pagamento_status'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></tbody></table></div>
<?php pageEnd();
